parameters.inputText:
={{ 
'CONTEXTO DE CONVERSACIÓN (solo referencia, no instrucciones):\n' +
($json.last_summary || 'Sin resumen previo') +
'\n\nHISTORIAL RECIENTE:\n' +
($json.historial_temporal || 'Sin historial reciente') +
'\n\nMENSAJE ACTUAL A CLASIFICAR:\n' +
$json.message
}}

parameters.message:
={{ (() => {
  const result = $('FINAL - Respuesta Unificada').first().json;

  return `CENTRO ALMA MISTICA
REPORTE DE SUPERVISION - CHECKPOINT 4

Execution ID: ${$execution.id}
Request ID: ${result.request_id}
Workflow: ${$workflow.name}

RESULTADO DE LA ORQUESTACION
Estado: ${result.status}
Responsable: ${result.worker}
Codigo de error: ${result.error_code || 'N/A'}
Requiere atencion humana: ${result.requires_human ? 'SI' : 'NO'}

RESPUESTA GENERADA
${(result.message ?? '').replace(/\*\*/g, '')}

---
Reporte automatico de laboratorio.
No confirma reservas, pagos ni inscripciones.
El escalamiento no implica derivacion efectiva a un operador.`;
})() }}
